#!/usr/bin/env python3
"""Refresh auto-generated sections in the profile README from the GitHub API.

Widgets (stats, streak, summary cards, view counter) already update on each
profile view — this script only rewrites marked markdown blocks that need a
commit: public repos table, language pie, and GitHub snapshot metrics.
"""

from __future__ import annotations

import json
import os
import re
import urllib.error
import urllib.request
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
README = ROOT / "README.md"
USERNAME = os.environ.get("PROFILE_USERNAME", "sumeeram")
TOKEN = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")

# Fallback blurbs when a public repo has no GitHub description yet.
REPO_BLURBS: dict[str, str] = {
    "profit-view": "Paper trading desk for TradingView-style signals — brackets, built-in tape, webhook alerts",
    "vidora": "Local-first YouTube downloader for Windows — Tauri 2, React, bundled yt-dlp + ffmpeg",
    "node-manager": "Cross-platform Node.js version manager — Rust core + CLI, desktop and web apps",
    "computer-networks": "Interactive bilingual ICT presentation on computer networks",
}

SKIP_REPOS = {USERNAME.lower(), "github_profile"}


def api(path: str) -> Any:
    url = f"https://api.github.com{path}"
    headers = {
        "Accept": "application/vnd.github+json",
        "User-Agent": f"{USERNAME}-profile-readme",
        "X-GitHub-Api-Version": "2022-11-28",
    }
    if TOKEN:
        headers["Authorization"] = f"Bearer {TOKEN}"
    req = urllib.request.Request(url, headers=headers)
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.load(resp)


def replace_block(text: str, name: str, body: str) -> str:
    start = f"<!-- AUTO:{name}:START -->"
    end = f"<!-- AUTO:{name}:END -->"
    pattern = re.compile(
        re.escape(start) + r".*?" + re.escape(end),
        re.DOTALL,
    )
    replacement = f"{start}\n{body.rstrip()}\n{end}"
    if not pattern.search(text):
        raise SystemExit(f"Missing markers for AUTO:{name} in README.md")
    return pattern.sub(replacement, text, count=1)


def fetch_repos() -> list[dict[str, Any]]:
    repos: list[dict[str, Any]] = []
    page = 1
    while True:
        batch = api(f"/users/{USERNAME}/repos?per_page=100&page={page}&type=owner&sort=updated")
        if not batch:
            break
        repos.extend(batch)
        if len(batch) < 100:
            break
        page += 1
    return repos


def language_totals(repos: list[dict[str, Any]]) -> Counter[str]:
    totals: Counter[str] = Counter()
    for repo in repos:
        if repo.get("fork") or repo["name"].lower() in SKIP_REPOS:
            continue
        try:
            langs = api(f"/repos/{USERNAME}/{repo['name']}/languages")
        except urllib.error.HTTPError:
            continue
        totals.update(langs)
    return totals


def pie_block(totals: Counter[str]) -> str:
    if not totals:
        return (
            "From non-fork public repositories (byte share):\n\n"
            "_No public language data yet._"
        )

    total = sum(totals.values()) or 1
    ranked = totals.most_common()
    top = ranked[:4]
    other = sum(v for _, v in ranked[4:])
    slices: list[tuple[str, int]] = [(name, round(100 * value / total)) for name, value in top]
    if other:
        slices.append(("Other", max(1, round(100 * other / total))))

    # Keep pie percentages summing near 100 after rounding.
    drift = 100 - sum(pct for _, pct in slices)
    if slices and drift:
        name, pct = slices[0]
        slices[0] = (name, pct + drift)

    lines = [
        "From non-fork public repositories (byte share). Regenerated by GitHub Actions.",
        "",
        "```mermaid",
        "%%{init: {'theme': 'dark', 'themeVariables': { 'pie1': '#3178C6', 'pie2': '#DEA584', 'pie3': '#563D7C', 'pie4': '#3572A5', 'pie5': '#89e051'}}}%%",
        "pie showData",
        "  title Public repo languages",
    ]
    for name, pct in slices:
        lines.append(f'  "{name}" : {pct}')
    lines.append("```")
    return "\n".join(lines)


def repos_block(repos: list[dict[str, Any]]) -> str:
    rows: list[str] = []
    for repo in repos:
        name = repo["name"]
        if repo.get("fork") or name.lower() in SKIP_REPOS:
            continue
        if repo.get("private"):
            continue
        title = f"**[{name}]({repo['html_url']})**"
        homepage = (repo.get("homepage") or "").strip()
        if homepage:
            if not homepage.startswith("http"):
                homepage = f"https://{homepage}"
            title += f" · [site]({homepage})"
        blurb = (repo.get("description") or "").strip() or REPO_BLURBS.get(name, "Public repository")
        lang = repo.get("language") or "—"
        stars = repo.get("stargazers_count") or 0
        rows.append(f"| {title} | {lang} | {stars} | {blurb} |")

    if not rows:
        table = "_No public non-fork repositories found._"
    else:
        header = "| Repo | Language | Stars | What it is |\n|:---|:---|---:|:---|"
        table = header + "\n" + "\n".join(rows)

    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    return (
        f"Auto-synced from the GitHub API · last refresh **{stamp}**\n\n"
        f"{table}"
    )


def snapshot_block(user: dict[str, Any], repos: list[dict[str, Any]], totals: Counter[str]) -> str:
    public = [r for r in repos if not r.get("fork") and r["name"].lower() not in SKIP_REPOS]
    stars = sum(r.get("stargazers_count") or 0 for r in public)
    total = sum(totals.values()) or 1
    ts_pct = round(100 * totals.get("TypeScript", 0) / total)
    rust_pct = round(100 * totals.get("Rust", 0) / total)
    return "\n".join(
        [
            "| Metric | Value |",
            "|:---|:---|",
            "| Years shipping software | 4+ |",
            "| Portfolio projects documented | 8 across 5 domains |",
            "| Roles at Syntax Genie | 3 (trainee → engineer) |",
            "| SLASSCOM team awards (2024) | 2× |",
            f"| Public repositories | {len(public)} |",
            f"| Public stars | {stars} |",
            f"| Public followers | {user.get('followers', 0)} |",
            f"| Public language focus | ~{ts_pct}% TypeScript · ~{rust_pct}% Rust |",
        ]
    )


def main() -> None:
    user = api(f"/users/{USERNAME}")
    repos = fetch_repos()
    totals = language_totals(repos)

    text = README.read_text(encoding="utf-8")
    text = replace_block(text, "PUBLIC_REPOS", repos_block(repos))
    text = replace_block(text, "LANG_PIE", pie_block(totals))
    text = replace_block(text, "SNAPSHOT", snapshot_block(user, repos, totals))
    README.write_text(text if text.endswith("\n") else text + "\n", encoding="utf-8")
    print("Updated README.md auto sections.")


if __name__ == "__main__":
    main()
